<?php require_once '../config.php'; login_required('admin'); $msg='';$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $uid=(int)$_POST['user_id'];$bid=(int)$_POST['book_id'];$due=$_POST['due_date'];$book=mysqli_fetch_assoc(mysqli_query($conn,"SELECT available FROM books WHERE id=$bid")); if(!$book||$book['available']<1)$error='Book not available.'; else { $q=mysqli_prepare($conn,"INSERT INTO issues(book_id,user_id,issue_date,due_date,status) VALUES(?,?,CURDATE(),?,'Issued')");mysqli_stmt_bind_param($q,'iis',$bid,$uid,$due); if(mysqli_stmt_execute($q)){mysqli_query($conn,"UPDATE books SET available=available-1 WHERE id=$bid");$msg='Book issued.';}else$error='Could not issue book.'; }} $users=mysqli_query($conn,"SELECT id,name FROM users WHERE role='user' ORDER BY name");$books=mysqli_query($conn,'SELECT id,title,available FROM books WHERE available>0 ORDER BY title');?><!doctype html><html><head><title>Issue Book</title><link rel="stylesheet" href="../assets/css/admin/issue_book.css"><link rel="stylesheet" href="../assets/css/admin/sidebar.css"></head><body><div class="layout"><?php include 'sidebar.php';?><main class="main"><h1>Issue Book</h1><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><div class="panel"><form method="post"><select name="user_id" required><option value="">Select User</option><?php while($u=mysqli_fetch_assoc($users)):?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endwhile;?></select><select name="book_id" required><option value="">Select Book</option><?php while($b=mysqli_fetch_assoc($books)):?><option value="<?=$b['id']?>"><?=e($b['title'])?> (<?=$b['available']?>)</option><?php endwhile;?></select><input type="date" name="due_date" required><button class="btn">Issue</button></form></div></main></div></body></html>
